  const store = sampleStore();
  const spaced = ADA.cardNumber.replace(/(\d{4})(?=\d)/g, '$1 ');
  const reply = handleCheckoutMessage(store, `11|AA${spaced}|AB${BOOK.barcode}|`, TODAY);
  assert.equal(reply, `121|AB${BOOK.id}|AH12/17/2026|`);
});
EOF
